18	enum PageScriptSources {
19	    /// Removes `token` from the address at document start (revision R2).
20	    ///
21	    /// A sign-in link is `https://<gateway>/?token=…`. By the time any script
22	    /// on that page runs, the token has already done its job: KiroCrew's auth
23	    /// middleware serves the page and sets the session and refresh cookies on
24	    /// that same response (`dashboard/token_auth.py:2891-3037` in 0.6.0).
25	    /// Leaving it in the address keeps a credential that is re-redeemable for
26	    /// 300 s in the back-forward list and in anything that reads the URL.
27	    ///
28	    /// Why document start, before the page's own scripts:
29	    ///  - React Router snapshots the location when it initialises. Rewriting
30	    ///    the URL after that leaves the router believing the query still holds
31	    ///    the token, and its next `setSearchParams` would write it back.
32	    ///  - It turns every sign-in load into the ordinary cookie-authenticated
33	    ///    load the app makes on every cold start, which is the most exercised
34	    ///    path the dashboard has.
35	    ///
36	    /// Cost, accepted: KiroCrew 0.6.0 reads `?token=` for one optional
37	    /// feature — a token carrying a `prompt` claim prefills the chat
38	    /// (`App-*.js`, the effect that calls its `YA()` decoder). Sign-in links
39	    /// minted by `kirocrew token` or the phone-access QR carry no prompt, so
40	    /// nothing is lost for them.
41	    ///
42	    /// Other parameters and the fragment are preserved; only `token` goes.
43	    /// `history.state` is passed through so the router's own state survives.
44	    static let stripSignInToken = #"""
45	    (function () {
46	      try {
47	        var params = new URLSearchParams(window.location.search);
48	        if (!params.has('token')) { return; }
49	        params.delete('token');
50	        var rest = params.toString();
51	        var clean = window.location.pathname + (rest ? '?' + rest : '') + window.location.hash;
52	        window.history.replaceState(window.history.state, '', clean);
53	      } catch (e) {
54	        // Never break the page over this. The token then stays in the
55	        // address, which is exactly the pre-R2 behaviour.
56	      }
57	    })();
58	    """#
59	
60	    /// The id of the `<style>` element `sessionBridge` adds.
61	    static let bannerStyleID = "latchkey-session-banner-hidden"
62	
63	    /// The session bridge (M4.2, R21, R22). Runs in the app's own content
64	    /// world, main frame only, at document start — so it is re-injected on
65	    /// every navigation, including the `location.assign('/')` KiroCrew does
66	    /// when a refresh chain is revoked, after which `mc-auth-required` fires.
67	    ///
68	    /// Three jobs:
69	    ///  1. Forward KiroCrew's `mc-auth-required` / `mc-auth-cleared` window
70	    ///     events to native. DOM events reach listeners in every content
71	    ///     world; the message handler exists only in the app's world, so the
72	    ///     page (or anything it loads from a CDN) cannot post to it.
73	    ///  2. Hide the page's own `#mc-session-expired` banner with CSS ONLY
74	    ///     (R22): the native sheet replaces it. Never remove the element or
75	    ///     click its ✕ — a startup gate reads it, and ✕ clears the client's
76	    ///     latches. `display:none` also keeps its input from autofocusing and
77	    ///     popping the keyboard.
78	    ///  3. Say `ready`. If native does not hear it, it removes the style again
79	    ///     (`revealSessionBanner`), so a broken bridge leaves the page's own
80	    ///     banner as the way to sign in. With no message handler at all the
81	    ///     style is never added in the first place.
82	    static let sessionBridge = #"""
83	    (function () {
84	      var handlers = window.webkit && window.webkit.messageHandlers;
85	      var handler = handlers && handlers.kiroSession;
86	      if (!handler) { return; }
87	      function post(event) {
88	        try { handler.postMessage({ event: event }); } catch (e) {}
89	      }
90	      try {
91	        var style = document.createElement('style');
92	        style.id = 'latchkey-session-banner-hidden';
93	        style.textContent = '#mc-session-expired{display:none!important}';
94	        (document.head || document.documentElement).appendChild(style);
95	      } catch (e) {}
96	      window.addEventListener('mc-auth-required', function () { post('auth-required'); });
97	      window.addEventListener('mc-auth-cleared', function () { post('auth-cleared'); });
98	      post('ready');
99	    })();
100	    """#
101	
102	    /// Undoes `sessionBridge`'s banner hiding: the handshake's fallback (R22).
103	    static let revealSessionBanner = #"""
104	    (function () {
105	      var s = document.getElementById('latchkey-session-banner-hidden');
106	      if (s) { s.remove(); }
107	    })();
108	    """#
109	
110	    /// The body of the async function the app runs in its own content world
111	    /// to ask the gateway something AS THE PAGE: M4's `/api/auth/me` check,
112	    /// and R32's `POST /api/auth/logout`. Arguments `path`, `method` and
113	    /// `timeoutMs` (0: none). Returns the HTTP status.
114	    ///
115	    /// Why the page and not URLSession: the request must carry the page's
116	    /// cookies (HttpOnly; the refresh cookie is scoped to /api/auth) and its
117	    /// Origin, which the gateway's CSRF check compares. `same-origin`
118	    /// credentials is the contract -- `omit` would make the logout a no-op
119	    /// that still answers 200. The header only marks the app's own requests,
120	    /// so the test gateway can tell them from the page's identical calls;
121	    /// servers ignore it. The abort is what keeps a check or a sign-out from
122	    /// hanging on a gateway that is down, or on a connection that is open
123	    /// and answers nothing; every caller in the app passes a timeout
124	    /// (`SessionManager.checkTimeout`, `DashboardSignOut.requestTimeout`).
125	    /// 0 still means none, for the contract's sake, but nothing sends it.
126	    static let sessionFetch = #"""
127	    const controller = new AbortController();
128	    const timer = timeoutMs > 0 ? setTimeout(function () { controller.abort(); }, timeoutMs) : null;
129	    try {
130	      const r = await fetch(path, {method: method, credentials: 'same-origin', cache: 'no-store',
131	                                   headers: {'X-Latchkey-Check': '1'}, signal: controller.signal});
132	      return r.status;
133	    } finally {
134	      if (timer !== null) { clearTimeout(timer); }
135	    }
136	    """#
137	
138	    /// The name `pageBackground` posts to. Registered in the app's own
139	    /// content world only, like the session bridge's.
140	    static let pageBackgroundHandler = "latchkeyPageBackground"
141	
142	    /// Reports the page's canvas colour (F9 §0.1 step 2): the strip above the
143	    /// web view is tinted with it, so page and strip read as one surface.
144	    ///
145	    /// Why not `WKWebView.themeColor`: KiroCrew 0.7.0 declares a fixed
146	    /// `theme-color` of `#0d0f12` and switches between twenty-odd dark AND
147	    /// light themes at runtime by `data-theme`, so the meta tag would paint a
148	    /// near-black bar above a light page. Why not `underPageBackgroundColor`:
149	    /// `RawWebView` overrides it to stop the pre-paint flash, and the getter
150	    /// then returns the override, not the page.
151	    ///
152	    /// The canvas takes `<html>`'s background, else `<body>`'s (CSS
153	    /// Backgrounds §2.11.2), which is what this reads. It posts the computed
154	    /// value — `rgb(…)`/`rgba(…)`, or `''` when the page paints nothing — on
155	    /// load, on attribute changes to `<html>`/`<body>` (a theme switch), on
156	    /// stylesheet insertion, on a colour-scheme change and after a background
157	    /// transition ends, coalesced to one read per frame and only on change.
158	    static let pageBackground = #"""
159	    (function () {
160	      var handlers = window.webkit && window.webkit.messageHandlers;
161	      var handler = handlers && handlers.latchkeyPageBackground;
162	      if (!handler) { return; }
163	      var last = null, pending = false;
164	      function clear(c) { return !c || c === 'transparent' || /^rgba\(.*,\s*0\)$/.test(c); }
165	      function read() {
166	        pending = false;
167	        var c = '';
168	        try {
169	          var d = document.documentElement, b = document.body;
170	          c = d ? getComputedStyle(d).backgroundColor : '';
171	          if (clear(c)) { c = b ? getComputedStyle(b).backgroundColor : ''; }
172	          if (clear(c)) { c = ''; }
173	        } catch (e) { c = ''; }
174	        if (c === last) { return; }
175	        last = c;
176	        try { handler.postMessage(c); } catch (e) {}
177	      }
178	      function schedule() {
179	        if (pending) { return; }
180	        pending = true;
181	        requestAnimationFrame(read);
182	      }
183	      var observer = new MutationObserver(function () {
184	        if (document.head) { observer.observe(document.head, {childList: true}); }
185	        if (document.body) { observer.observe(document.body, {attributes: true}); }
186	        schedule();
187	      });
188	      observer.observe(document.documentElement, {attributes: true, childList: true});
189	      document.addEventListener('DOMContentLoaded', schedule);
190	      window.addEventListener('load', schedule);
191	      document.addEventListener('transitionend', schedule, true);
192	      try { matchMedia('(prefers-color-scheme: dark)').addEventListener('change', schedule); } catch (e) {}
193	      schedule();
194	    })();
195	    """#
196	
197	    /// The name `appBarObserver` posts to, in the app's own content world.
198	    static let appBarHandler = "latchkeyAppBar"
199	
200	    /// Reports the finger's travel to the app bar (F15 §4a).
201	    ///
202	    /// Why a page script and not the web view's `UIScrollView`: KiroCrew
203	    /// 0.7.0's shell is `h-dvh` with `overflow-hidden` and inner scrollers,
204	    /// so the document never scrolls and the scroll view never moves. Only an
205	    /// element inside the page does, and WebKit reports that only to the page.
206	    ///
207	    /// It observes and never takes part. Every listener is `passive` (it
208	    /// cannot call `preventDefault`, so it cannot stop a scroll) and on
209	    /// `window` in the capture phase, which sees a scroll of ANY element
210	    /// without reading the page's markup (F15 §3). It lives in the app's
211	    /// content world, invisible to the page.
212	    ///
213	    /// Posts `{p: 's'|'m'|'e', dx, dy, r}`: a touch-down, a move coalesced to
214	    /// one per frame, a lift. dx/dy are screen points. `r` is the largest
215	    /// vertical scroll range of anything that scrolled during the touch — 0
216	    /// when nothing did, which is how a page too short to scroll is told
217	    /// apart from one that scrolls. A change of viewport size (the bar itself
218	    /// retracting) re-bases the finger instead of counting as travel.
219	    ///
220	    /// And `{p: 'x', r}`, the page's extent: the largest vertical scroll range
221	    /// of the document or of any element whose `overflow-y` lets it scroll
222	    /// (form controls aside), in screen points, touch or no touch. The bar is
223	    /// hidden by default, and a page with no range must keep it (F15 §4b), so
224	    /// the app has to know before the owner touches anything. Measured at most
225	    /// every 500 ms, after the document loads, resizes, mutates or scrolls, and
226	    /// posted when it changes and always at `load`. It reads layout, never
227	    /// the page's markup or text.
228	    static let appBarObserver = #"""
229	    (function () {
230	      var handlers = window.webkit && window.webkit.messageHandlers;
231	      var handler = handlers && handlers.latchkeyAppBar;
232	      if (!handler) { return; }
233	      var opts = {capture: true, passive: true};
234	      var active = false, pending = false, x = 0, y = 0, w = 0, h = 0, dx = 0, dy = 0, range = 0;
235	      var extent = -1, due = 0;
236	      function scale() { return window.visualViewport ? window.visualViewport.scale : 1; }
237	      function post(m) { try { handler.postMessage(m); } catch (e) {} }
238	      function send(p) {
239	        post({p: p, dx: dx, dy: dy, r: range});
240	        dx = 0; dy = 0;
241	      }
242	      function flush() { pending = false; if (active && (dx || dy)) { send('m'); } }
243	      function base(t) { x = t.clientX; y = t.clientY; w = window.innerWidth; h = window.innerHeight; }
244	      function end() {
245	        if (!active) { return; }
246	        if (dx || dy) { send('m'); }
247	        active = false;
248	        send('e');
249	      }
250	      function overflowY(el) {
251	        return (el && typeof getComputedStyle === 'function') ? getComputedStyle(el).overflowY : 'visible';
252	      }
253	      function measure(always) {
254	        due = 0;
255	        var r = 0;
256	        try {
257	          var se = document.scrollingElement;
258	          if (se) {
259	            var clip = /^(hidden|clip)$/;
260	            var d = se.scrollHeight - se.clientHeight;
261	            if (d > 0 && !clip.test(overflowY(document.documentElement)) && !clip.test(overflowY(document.body))) { r = d; }
262	          }
263	          var all = document.querySelectorAll ? document.querySelectorAll('*') : [];
264	          for (var i = 0; i < all.length; i++) {
265	            var el = all[i], e = el.scrollHeight - el.clientHeight;
266	            if (e > r && el !== se && !/^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName)
267	                && /^(auto|scroll|overlay)$/.test(overflowY(el))) { r = e; }
268	          }
269	        } catch (err) { return; }
270	        r = Math.round(r * scale());
271	        if (always || r !== extent) { extent = r; post({p: 'x', r: r}); }
272	      }
273	      function soon() { if (!due && typeof setTimeout === 'function') { due = setTimeout(measure, 500); } }
274	      window.addEventListener('touchstart', function (e) {
275	        if (e.touches.length !== 1) { end(); return; }
276	        active = true; dx = 0; dy = 0; range = 0;
277	        base(e.touches[0]);
278	        send('s');
279	      }, opts);
280	      window.addEventListener('touchmove', function (e) {
281	        if (!active) { return; }
282	        if (e.touches.length !== 1) { end(); return; }
283	        var t = e.touches[0];
284	        if (window.innerWidth !== w || window.innerHeight !== h) { base(t); return; }
285	        var k = scale();
286	        dx += (t.clientX - x) * k; dy += (t.clientY - y) * k;
287	        x = t.clientX; y = t.clientY;
288	        if (!pending) { pending = true; requestAnimationFrame(flush); }
289	      }, opts);
290	      window.addEventListener('touchend', end, opts);
291	      window.addEventListener('touchcancel', end, opts);
292	      window.addEventListener('scroll', function (e) {
293	        soon();
294	        if (!active) { return; }
295	        var el = (e.target === document || e.target === window) ? document.scrollingElement : e.target;
296	        if (!el || typeof el.scrollHeight !== 'number') { return; }
297	        var r = (el.scrollHeight - el.clientHeight) * scale();
298	        if (r > range) { range = r; }
299	      }, opts);
300	      window.addEventListener('DOMContentLoaded', soon, opts);
301	      window.addEventListener('resize', soon, opts);
302	      window.addEventListener('load', function () { measure(true); }, opts);
303	      if (typeof MutationObserver === 'function') {
304	        new MutationObserver(soon).observe(document, {childList: true, subtree: true, attributes: true, characterData: true});
305	      }
306	    })();
307	    """#
308	
309	    /// Parses what `pageBackground` posts into sRGB components in 0…1.
310	    /// `nil` for anything else — an empty report, `color(…)`, `oklch(…)` —
311	    /// and for a colour that is not fully opaque: the strip would then show
312	    /// the app's background through it and match nothing. The caller falls
313	    /// back to the system background, which is the web view's own before
314	    /// the first paint.
315	    nonisolated static func opaqueRGB(fromCSS css: String) -> (red: Double, green: Double, blue: Double)? {
316	        let s = css.trimmingCharacters(in: .whitespaces).lowercased()
317	        let body: Substring
318	        if s.hasPrefix("rgba("), s.hasSuffix(")") {
319	            body = s.dropFirst(5).dropLast()
320	        } else if s.hasPrefix("rgb("), s.hasSuffix(")") {
321	            body = s.dropFirst(4).dropLast()
322	        } else {
323	            return nil
324	        }
325	        let parts = body.split(whereSeparator: { $0 == "," || $0 == " " || $0 == "/" })
326	            .compactMap { Double($0) }
327	        guard parts.count == 3 || parts.count == 4,
328	              parts.prefix(3).allSatisfy({ (0...255).contains($0) }) else { return nil }
329	        if parts.count == 4, parts[3] < 1 { return nil }
330	        return (parts[0] / 255, parts[1] / 255, parts[2] / 255)
331	    }
332	}
