  const text = await r.text();
  return {status: r.status, body: text, auth: r.headers.get('X-Auth-Required') !== null};
} catch (e) {
  return {status: 0, body: '', auth: false};
} finally {
  delete store[id];
  if (timer !== null) { clearTimeout(timer); }
}
