/// Runs `script` as an async function in the app's content world, with
/// the page's cookies and Origin (F3's share, like the M4 check). Its
/// result, or nil when there is no page or the call threw.
func sessionCall(_ script: String, arguments: [String: Any]) async -> Any? {
    guard let webView else { return nil }
    do {
        return try await webView.callAsyncJavaScript(script, arguments: arguments,
                                                     in: nil, contentWorld: SessionManager.world)
    } catch {
        logger.log("Share: a page-world call failed: \(LogRedaction.describe(error))")
        return nil
    }
}

func revealSessionBanner() {
    webView?.evaluateJavaScript(PageScriptSources.revealSessionBanner, in: nil,

/// A request of the app's own was refused with 403 + `X-Auth-Required`
/// (F3's share). The page may not have noticed yet -- its own next
/// request will -- so the sheet is asked for now. A check in flight
/// cannot mark the session active over this; a sign-in, or the page
/// recovering by itself, does.
func requireSignIn() {
    guard state != .needsToken else {
        isTokenSheetPresented = true
        return
    }
    logger.log("Session: the gateway refused an app request for want of a session")
    authGeneration += 1
    state = .needsToken
    isTokenSheetPresented = true
    Task { await verify(afterRedemption: false) }
}

// MARK: - Installation

@Published var socksRelayFallbacks = 0
/// F3's share: items admitted to the inbox, confirmed by a gateway
/// (sent, or queued behind a busy session), failed attempts, and items
/// the sweep removed unsent.
@Published var sharesReceived = 0
@Published var sharesSent = 0
@Published var sharesQueued = 0
@Published var sharesFailed = 0
@Published var sharesSwept = 0

